if(player.dead<=0){const px=player.x,py=player.y;ctx.fillStyle='#0c1529';rr(px+2,py+4,player.w,player.h,5);ctx.fill();ctx.fillStyle=player.dashing>0?'#d7ffe8':'#a9f2c9';rr(px,py,player.w,player.h,5);ctx.fill();ctx.fillStyle='#f0fbef';ctx.fillRect(px+5,py+8,12,8);ctx.fillStyle='#17263b';ctx.fillRect(px+(player.face>0?13:7),py+10,3,4);ctx.fillStyle='#7ed6aa';ctx.fillRect(px+4,py+player.h-5,6,5);ctx.fillRect(px+13,py+player.h-5,6,5);}
